namespace SirketMotoru.CanliPano;

internal static class YazilimBorsasiHtml
{
    public const string Icerik = """
<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Yazılım Borsası v5</title>
<style>
:root{color-scheme:dark;--bg:#040711;--p:#0b1525;--p2:#101d30;--l:#23364f;--t:#eef5ff;--m:#8fa4c0;--g:#42e1a0;--b:#62a8ff;--r:#ff6b7d;--y:#ffd166;--s:0 16px 48px #0008}*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:radial-gradient(circle at 8% 0,#10274a 0,transparent 34%),radial-gradient(circle at 92% 0,#25154c 0,transparent 30%),var(--bg);color:var(--t);font-family:Segoe UI,Arial,sans-serif}body{padding:10px}.shell{max-width:2200px;margin:auto}.top{position:sticky;top:5px;z-index:20;display:flex;justify-content:space-between;align-items:center;gap:10px;padding:12px 14px;border:1px solid var(--l);border-radius:15px;background:#091322ed;box-shadow:var(--s)}.brand{font-weight:950;font-size:19px}.brand small{display:block;color:var(--m);font-size:9px;margin-top:3px;font-weight:500}.status,.tabs,.tags{display:flex;gap:7px;flex-wrap:wrap;align-items:center}.status{justify-content:flex-end}.pill,.tag{padding:5px 8px;border:1px solid var(--l);border-radius:999px;background:#091525;color:var(--m);font-size:9px}.pill b{color:var(--t)}.dot{display:inline-block;width:8px;height:8px;border-radius:50%;background:var(--r);margin-right:5px}.dot.ok{background:var(--g);box-shadow:0 0 12px var(--g)}.tabs{margin:11px 0}.tab{cursor:pointer;padding:9px 12px;border:1px solid var(--l);border-radius:999px;background:#091525;color:var(--m);font-weight:850}.tab.active{background:linear-gradient(135deg,var(--g),var(--b));color:#03151c;border-color:transparent}.page[hidden]{display:none!important}.page:not([hidden]){display:grid;gap:11px}.kpis{display:grid;grid-template-columns:repeat(10,minmax(115px,1fr));gap:8px}.kpi,.company{padding:10px;border:1px solid var(--l);border-radius:12px;background:linear-gradient(180deg,var(--p2),#091321)}.kpi span,.sub{display:block;color:var(--m);font-size:8px}.kpi b{display:block;margin-top:7px;font-size:17px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.card{border:1px solid var(--l);border-radius:14px;background:linear-gradient(180deg,#101c30ed,#08101ded);box-shadow:var(--s);overflow:hidden}.head{display:flex;justify-content:space-between;align-items:center;gap:8px;padding:11px 13px;border-bottom:1px solid var(--l)}.title{font-weight:950;font-size:13px}.companies{display:grid;grid-template-columns:repeat(4,minmax(280px,1fr));gap:8px;padding:9px}.company{position:relative;overflow:hidden}.company:before{content:"";position:absolute;left:0;top:0;bottom:0;width:4px;background:var(--c,var(--b))}.companyTop{display:flex;justify-content:space-between;gap:7px}.name{font-size:16px;font-weight:950}.rank{font-size:22px;font-weight:1000;color:var(--y)}.state{display:inline-block;margin-top:5px;padding:3px 6px;border:1px solid #28634f;border-radius:999px;color:var(--g);font-size:8px}.state.off{color:var(--r);border-color:#743746}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:6px;margin-top:8px}.metric{padding:7px;border:1px solid #1d2d45;border-radius:8px;background:#0d192b;min-width:0}.metric span{display:block;color:var(--m);font-size:7px}.metric b{display:block;margin-top:3px;font-size:11px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.bar{height:6px;background:#17253b;border-radius:99px;overflow:hidden;margin-top:8px}.bar i{display:block;height:100%;background:linear-gradient(90deg,var(--b),var(--g))}.tablewrap{overflow:auto;max-height:720px}table{width:100%;border-collapse:collapse;min-width:1100px;font-size:9px}th{position:sticky;top:0;background:#101c30;color:var(--m);padding:8px;text-align:left;font-size:8px;text-transform:uppercase;border-bottom:1px solid var(--l)}td{padding:8px;border-bottom:1px solid #1b2a41;vertical-align:top}.num{text-align:right}.good{color:var(--g)}.bad{color:var(--r)}.warn{color:var(--y)}.muted{color:var(--m)}.two{display:grid;grid-template-columns:1fr 1fr;gap:11px}.log{height:500px;overflow:auto;padding:9px;background:#050a12;font:9px/1.45 Consolas,monospace}.line{display:grid;grid-template-columns:75px 75px 1fr;gap:7px;padding:4px 0;border-bottom:1px dashed #18253a}.sep{height:1px;background:linear-gradient(90deg,transparent,var(--l),transparent)}.empty{padding:20px;text-align:center;color:var(--m)}@media(max-width:1750px){.kpis{grid-template-columns:repeat(5,1fr)}.companies{grid-template-columns:repeat(3,1fr)}}@media(max-width:1250px){.companies{grid-template-columns:repeat(2,1fr)}.two{grid-template-columns:1fr}}@media(max-width:760px){body{padding:5px}.top{position:static;flex-direction:column;align-items:flex-start}.status{justify-content:flex-start}.kpis{grid-template-columns:repeat(2,1fr)}.companies{grid-template-columns:1fr}}
</style></head><body><div class="shell"><header class="top"><div class="brand">YAZILIM BORSASI v5<small>20.000 müşteri · işletim sistemleri · kapasite · ürünler · risk</small></div><div class="status"><span class="pill"><i id="dot" class="dot"></i><b id="conn">BAĞLANIYOR</b></span><span class="pill">Tick <b id="tick">0</b></span><span class="pill">Müşteri <b id="customers">0</b></span><span class="pill">Gecikme <b id="latency">—</b></span><span id="clock" class="pill">—</span></div></header><nav id="tabs" class="tabs"><button class="tab active" data-view="home">Ana Sayfa</button><button class="tab" data-view="overview">Genel Borsa</button><button class="tab" data-view="systems">İşletim Sistemleri</button><button class="tab" data-view="apps">Uygulamalar</button><button class="tab" data-view="protocols">Protokoller</button><button class="tab" data-view="services">Hizmetler & Kapasite</button><button class="tab" data-view="finance">Finans</button><button class="tab" data-view="operations">Sözleşmeler & Yatırımlar</button><button class="tab" data-view="security">Risk & Akış</button></nav><main id="home" class="page"></main><main id="overview" class="page" hidden></main><main id="systems" class="page" hidden></main><main id="apps" class="page" hidden></main><main id="protocols" class="page" hidden></main><main id="services" class="page" hidden></main><main id="finance" class="page" hidden></main><main id="operations" class="page" hidden></main><main id="security" class="page" hidden></main></div>
<script>
'use strict';const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],money=v=>new Intl.NumberFormat('tr-TR',{style:'currency',currency:'TRY',maximumFractionDigits:2}).format(Number(v||0)),num=v=>new Intl.NumberFormat('tr-TR',{maximumFractionDigits:2}).format(Number(v||0)),int=v=>new Intl.NumberFormat('tr-TR',{maximumFractionDigits:0}).format(Number(v||0)),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const S={active:'home',loading:false,colors:['#42e1a0','#62a8ff','#b58cff','#ffd166','#42d6ee','#ff6b7d']};
function cap(c){const hs=(c.hizmetler||[]).filter(h=>h.aktif),ps=c.isletim?.urunler||[],processing=hs.reduce((a,h)=>a+Number(h.azamiEszamanliIs||0),0),appCapacity=ps.reduce((a,p)=>a+Number(p.kullaniciKapasitesi||0),0),users=ps.reduce((a,p)=>a+Number(p.aktifKullaniciSayisi||0),0),purchased=ps.reduce((a,p)=>a+Number(p.satinAlinanKullaniciKapasitesi||0),0),infra=ps.reduce((a,p)=>a+Number(p.altyapiKapasiteBonusu||0),0);return{processing,appCapacity,users,purchased,infra,occ:appCapacity?users*100/appCapacity:0}}
function companies(d){return(d.sirketler||[]).map(c=>({...c,cap:cap(c),value:Number(c.isletim?.sirketDegeri||0)})).sort((a,b)=>b.value-a.value)}function view(id){const t=document.getElementById(id)||$('#home');S.active=t.id;$$('.page').forEach(p=>p.hidden=p!==t);$$('.tab').forEach(b=>b.classList.toggle('active',b.dataset.view===t.id));history.replaceState(null,'',`#${t.id}`)}$('#tabs').addEventListener('click',e=>{const b=e.target.closest('[data-view]');if(b){e.preventDefault();view(b.dataset.view)}});
function kpis(d,cs){const g=d.genel||{},v=cs.reduce((a,c)=>a+c.value,0),proc=cs.reduce((a,c)=>a+c.cap.processing,0),ac=cs.reduce((a,c)=>a+c.cap.appCapacity,0),users=cs.reduce((a,c)=>a+c.cap.users,0);return `<section class="kpis">${[['Toplam değer',money(v)],['Toplam kasa',money(g.toplamSirketKasasi)],['Toplam borç',money(g.toplamBorc)],['İşlem kapasitesi',int(proc)],['Uygulama kapasitesi',int(ac)],['Aktif kullanıcı',int(users)],['Müşteri',int(g.toplamMusteriSayisi)],['Piyasadaki uygulama',int(g.piyasadakiUygulamaSayisi)],['Piyasadaki protokol',int(g.piyasadakiProtokolSayisi)],['Bağlı şirket',`${int(g.bagliSirketSayisi)}/${int(g.toplamSirketSayisi)}`]].map(x=>`<div class="kpi"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}</section>`}
function overview(d,cs){return `${kpis(d,cs)}<section class="card"><div class="head"><div><div class="title">ŞİRKET DEĞER VE KAPASİTE SIRALAMASI</div><span class="sub">Değer; ürün, kullanıcı, kapasite, geçmiş, kalite, borç, yatırım ve riskten hesaplanır.</span></div></div><div class="companies">${cs.map((c,i)=>`<article class="company" style="--c:${S.colors[i%S.colors.length]}"><div class="companyTop"><div><div class="name">${esc(c.sirketAdi)}</div><span class="state ${c.bagli?'':'off'}">${c.bagli?'BAĞLI':'KAPALI'}</span></div><div class="rank">#${i+1}</div></div><div class="metrics">${[['Değer',money(c.value)],['Kasa',money(c.kasa)],['Net gelir',money(c.netGelir)],['İşlem kap.',int(c.cap.processing)],['App kap.',int(c.cap.appCapacity)],['Kullanıcı',int(c.cap.users)],['Doluluk',`%${num(c.cap.occ)}`],['Operasyon riski',num(c.isletim?.operasyonRiski)],['Teknik borç',num(c.isletim?.teknikBorc)]].map(x=>`<div class="metric"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}</div><div class="bar"><i style="width:${Math.min(100,c.cap.occ)}%"></i></div><div class="tags"><span class="tag good">K ${num(c.kodKalitesiPuani)}</span><span class="tag good">P ${num(c.performansPuani)}</span><span class="tag good">G ${num(c.guvenlikPuani)}</span><span class="tag">Satın kap. ${int(c.cap.purchased)}</span><span class="tag warn">Altyapı bonusu ${int(c.cap.infra)}</span></div></article>`).join('')}</div></section>`}
function systems(d){const rows=(d.uygulamaPiyasasi||[]).filter(x=>(x.uygulama?.urunTuru||x.urun?.urunTuru)==='isletim-sistemi');return `<section class="card"><div class="head"><div><div class="title">İŞLETİM SİSTEMİ PAZARI</div><span class="sub">Her müşteri bir sistem seçer; sistemler aktif protokol ve kapasite olmadan çalışamaz.</span></div></div><div class="tablewrap"><table><thead><tr><th>Şirket</th><th>Sistem</th><th>Protokoller</th><th class="num">Kullanıcı</th><th class="num">Kapasite</th><th class="num">Doluluk</th><th class="num">Kalite</th><th>Durum</th></tr></thead><tbody>${rows.map(x=>{const a=x.uygulama||{},u=x.urun||{},cap=Number(u.kullaniciKapasitesi||0),users=Number(u.aktifKullaniciSayisi||0);return `<tr><td><b>${esc(x.sirketAdi)}</b></td><td><b>${esc(a.uygulamaAdi)}</b><div class="muted">${esc(a.uygulamaKimligi)} v${esc(a.surum)}</div></td><td>${(a.desteklenenProtokoller||[]).map(p=>`<span class="tag">${esc(p)}</span>`).join(' ')||'<span class="bad">Protokol yok</span>'}</td><td class="num">${int(users)}</td><td class="num">${int(cap)}</td><td class="num">%${num(cap?users*100/cap:0)}</td><td class="num">${num(u.urunKalitesi)}</td><td class="${x.piyasada&&u.aktif?'good':'bad'}">${x.piyasada&&u.aktif?'AKTİF':'PASİF'}</td></tr>`}).join('')||'<tr><td colspan="8" class="empty">Henüz piyasada işletim sistemi yok. Mevcut uygulamalar OS/protokol yapılandırılana kadar pasif kalır.</td></tr>'}</tbody></table></div></section>`}
function apps(d){const rows=(d.uygulamaPiyasasi||[]).filter(x=>(x.uygulama?.urunTuru||x.urun?.urunTuru)!=='isletim-sistemi');return `<section class="card"><div class="head"><div><div class="title">UYGULAMA VE ÜRÜN PAZARI</div><span class="sub">Her uygulama işletim sistemi ve ortak protokol üzerinden dağıtılır.</span></div></div><div class="tablewrap"><table><thead><tr><th>Şirket</th><th>Ürün</th><th>Tür</th><th>Platform desteği</th><th>Protokoller</th><th class="num">Kullanıcı</th><th class="num">Kapasite</th><th class="num">Gelir</th><th>Durum</th></tr></thead><tbody>${rows.map(x=>{const a=x.uygulama||{},u=x.urun||{};return `<tr><td><b>${esc(x.sirketAdi)}</b></td><td><b>${esc(a.uygulamaAdi)}</b><div class="muted">${esc(a.uygulamaKimligi)}</div></td><td>${esc(a.urunTuru||a.kategori||'uygulama')}</td><td>${(a.desteklenenPlatformlar||[]).map(p=>`<span class="tag good">${esc(p)}</span>`).join(' ')||'8090 seçimi gerekli'}</td><td>${(a.desteklenenProtokoller||[]).map(p=>`<span class="tag">${esc(p)}</span>`).join(' ')||'<span class="bad">Yok</span>'}</td><td class="num">${int(u.aktifKullaniciSayisi)}</td><td class="num">${int(u.kullaniciKapasitesi)}</td><td class="num good">${money(u.toplamGelir)}</td><td class="${x.piyasada&&u.aktif?'good':'bad'}">${x.piyasada&&u.aktif?'AKTİF':'PASİF/YAPILANDIRMA'}</td></tr>`}).join('')||'<tr><td colspan="9" class="empty">Uygulama yok.</td></tr>'}</tbody></table></div></section>`}
function protocols(d){const rows=d.protokolPiyasasi||[];return `<section class="card"><div class="head"><div class="title">ÖZEL PROTOKOL PİYASASI</div></div><div class="tablewrap"><table><thead><tr><th>Şirket</th><th>Protokol</th><th>Şema</th><th>Yetkinlik</th><th>Uyumluluk</th><th>Durum</th></tr></thead><tbody>${rows.map(x=>{const p=x.teknikProtokol||{};return `<tr><td><b>${esc(x.sirketAdi)}</b></td><td><b>${esc(p.protokolAdi)}</b><div class="muted">${esc(p.protokolKimligi)} v${esc(p.surum)}</div></td><td>${esc(p.semaKimligi||'-')}</td><td>${int((p.yetkinlikler||[]).length)}</td><td>${(p.uyumluProtokoller||[]).map(y=>`<span class="tag">${esc(y)}</span>`).join(' ')||'-'}</td><td class="${x.piyasada?'good':'warn'}">${x.piyasada?'PİYASADA':'TEKNİK İLAN'}</td></tr>`}).join('')||'<tr><td colspan="6" class="empty">Protokol yok.</td></tr>'}</tbody></table></div></section>`}
function services(d,cs){const rows=d.hizmetPiyasasi||[];return `${kpis(d,cs)}<section class="card"><div class="head"><div><div class="title">HİZMET PİYASASI VE İŞLEM KAPASİTESİ</div><span class="sub">Sağlayıcı kapasitesi 8090 kalıcı kaydı ve yatırımlarından gelir.</span></div></div><div class="tablewrap"><table><thead><tr><th>Hizmet</th><th class="num">Talep</th><th class="num">Bütçe</th><th class="num">Sağlayıcı</th><th>Kapasite ve fiyatlar</th></tr></thead><tbody>${rows.map(h=>`<tr><td><b>${esc(h.hizmetKimligi)}</b><div class="muted">v${esc(h.hizmetSurumu)}</div></td><td class="num">${int(h.talepSayisi)}</td><td class="num">${money(h.toplamTalepButcesi)}</td><td class="num">${int(h.saglayiciSayisi)}</td><td>${(h.saglayicilar||[]).map(s=>`<span class="tag ${s.bagli?'good':'bad'}">${esc(s.sirketAdi)} · ${money(s.birimFiyat)} · kap ${int(s.azamiEszamanliIs)}</span>`).join(' ')||'-'}</td></tr>`).join('')}</tbody></table></div></section>`}
function finance(d,cs){const loans=d.krediPiyasasi||[];return `<section class="two"><div class="card"><div class="head"><div class="title">ŞİRKET FİNANSI</div></div><div class="tablewrap"><table><thead><tr><th>Şirket</th><th class="num">Değer</th><th class="num">Kasa</th><th class="num">Borç</th><th class="num">Gider</th><th class="num">Ödenemeyen</th><th class="num">Not</th></tr></thead><tbody>${cs.map(c=>`<tr><td><b>${esc(c.sirketAdi)}</b></td><td class="num good">${money(c.value)}</td><td class="num">${money(c.kasa)}</td><td class="num bad">${money(c.isletim?.toplamBorc)}</td><td class="num">${money(c.isletim?.toplamIsletmeGideri)}</td><td class="num bad">${money(c.isletim?.odenemeyenGider)}</td><td class="num">${int(c.isletim?.krediNotu)}</td></tr>`).join('')}</tbody></table></div></div><div class="card"><div class="head"><div class="title">AKTİF KREDİLER</div></div><div class="tablewrap"><table><thead><tr><th>Şirket</th><th>Tür</th><th class="num">Kalan</th><th class="num">Taksit</th><th class="num">Gecikme</th></tr></thead><tbody>${loans.map(x=>`<tr><td>${esc(x.sirketAdi)}</td><td>${esc(x.kredi?.krediTuru)}</td><td class="num bad">${money(x.kredi?.kalanBorc)}</td><td class="num">${money(x.kredi?.taksitTutari)}</td><td class="num">${int(x.kredi?.gecikmeSayisi)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">Kredi yok.</td></tr>'}</tbody></table></div></div></section>`}
function operations(d){const cs=d.sozlesmePiyasasi||[],is=d.yatirimPiyasasi||[];return `<section class="two"><div class="card"><div class="head"><div class="title">SLA SÖZLEŞMELERİ</div></div><div class="tablewrap"><table><thead><tr><th>Şirket</th><th>Sözleşme</th><th class="num">Ödeme</th><th class="num">Kapasite</th><th class="num">Başarı</th><th class="num">İhlal</th></tr></thead><tbody>${cs.map(x=>`<tr><td>${esc(x.sirketAdi)}</td><td>${esc(x.sozlesme?.baslik)}</td><td class="num good">${money(x.sozlesme?.tickOdemesi)}</td><td class="num">${int(x.sozlesme?.gerekliKapasite)}</td><td class="num">${int(x.sozlesme?.basariliTickSayisi)}</td><td class="num bad">${int(x.sozlesme?.ihlalSayisi)}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">Sözleşme yok.</td></tr>'}</tbody></table></div></div><div class="card"><div class="head"><div class="title">YATIRIMLAR</div></div><div class="tablewrap"><table><thead><tr><th>Şirket</th><th>Yatırım</th><th class="num">Seviye</th></tr></thead><tbody>${is.map(x=>`<tr><td>${esc(x.sirketAdi)}</td><td>${esc(x.yatirimTuru)}</td><td class="num good">${int(x.seviye)}</td></tr>`).join('')||'<tr><td colspan="3" class="empty">Yatırım yok.</td></tr>'}</tbody></table></div></div></section>`}
function security(d,cs){const ev=(d.olaylar||[]).slice().reverse();return `<section class="two"><div class="card"><div class="head"><div><div class="title">RİSK VE DAYANIKLILIK</div><span class="sub">Kaliteli kod avantajdır; ölçek ve dış olay riski sıfırlamaz.</span></div></div><div class="tablewrap"><table><thead><tr><th>Şirket</th><th class="num">Güvenlik</th><th class="num">Operasyon riski</th><th class="num">Teknik borç</th><th class="num">Bakım baskısı</th><th class="num">Engellenen</th><th class="num">Başarılı saldırı</th></tr></thead><tbody>${cs.map(c=>`<tr><td><b>${esc(c.sirketAdi)}</b></td><td class="num good">${num(c.guvenlikPuani)}</td><td class="num warn">${num(c.isletim?.operasyonRiski)}</td><td class="num">${num(c.isletim?.teknikBorc)}</td><td class="num">${num(c.isletim?.bakimBaskisi)}</td><td class="num good">${int(c.engellenenSaldiriSayisi)}</td><td class="num bad">${int(c.basariliSaldiriSayisi)}</td></tr>`).join('')}</tbody></table></div></div><div class="card"><div class="head"><div class="title">CANLI MOTOR AKIŞI</div></div><div id="log" class="log">${ev.map(x=>`<div class="line"><span>${esc(x.zaman||x.zamanDamgasi||'—')}</span><b>${esc(x.seviye||x.tur||'BİLGİ')}</b><span>${esc(x.mesaj||x.aciklama||JSON.stringify(x))}</span></div>`).join('')||'<div class="empty">Akış yok.</div>'}</div></div></section>`}
function render(d){const cs=companies(d),parts={overview:overview(d,cs),systems:systems(d),apps:apps(d),protocols:protocols(d),services:services(d,cs),finance:finance(d,cs),operations:operations(d),security:security(d,cs)};$('#home').innerHTML=Object.values(parts).join('<div class="sep"></div>');for(const [id,h] of Object.entries(parts))document.getElementById(id).innerHTML=h;view(S.active)}async function refresh(){if(S.loading)return;S.loading=true;const start=performance.now();try{const r=await fetch(`/api/durum?v=5&t=${Date.now()}`,{cache:'no-store'});if(!r.ok)throw new Error(`HTTP ${r.status}`);const d=await r.json();render(d);$('#dot').className='dot ok';$('#conn').textContent='CANLI';$('#tick').textContent=d.motor?.tickNumarasi||0;$('#customers').textContent=int(d.genel?.toplamMusteriSayisi);$('#latency').textContent=`${Math.round(performance.now()-start)} ms`}catch(e){$('#dot').className='dot';$('#conn').textContent='BAĞLANTI YOK'}finally{S.loading=false}}setInterval(()=>$('#clock').textContent=new Date().toLocaleTimeString('tr-TR'),250);setInterval(refresh,500);view(document.getElementById(location.hash.slice(1))?location.hash.slice(1):'home');refresh();
</script></body></html>
